{"CommandLine":"python -c "
import os, re

keywords = [
    'GILE', 'Goodness', 'Intuition', 'Love', 'Elegance', 'HEM', 'Footprint',
    'Concrete Mechanisms', 'Relational Meaning', 'Form', 'Length', 'Width', 'Height', 'Time',
    'truth label', 'Indeterminate', 'Meta-Indeterminate', 'Tralse', 'five-valued', '5-valued',
    'Belnap', 'Priest', 'mutual information', 'Fleiss', 'kappa', 'interrater', 'agreement',
    'reliability', 'completeness', 'exhaustiveness', 'entropy', 'residual exhaustion',
    'effective rank', 'ablation', 'truth axes', 'quaternion', 'Potentiality Deficit', 'Potentiality-Deficit',
    'PD', 'Crystal', 'Graph', 'Myrion', 'MR', '4/3', '0.93', 'domain weight', 'hem_gile'
]

matches = []
repo_root = '.'

for root, dirs, files in os.walk(repo_root):
    if '.git' in dirs:
        dirs.remove('.git')
    for file in files:
        if file.endswith(('.png', '.gz', '.pyc', '.pptx', '.pdf')):
            continue
        rel_path = os.path.relpath(os.path.join(root, file), repo_root)
        try:
            with open(rel_path, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.readlines()
                for idx, line in enumerate(lines):
                    for kw in keywords:
                        if re.search(r'\b' + re.escape(kw) + r'\b', line, re.IGNORECASE):
                            matches.append({
                                'file': rel_path,
                                'line': idx + 1,
                                'kw': kw,
                                'text': line.strip()
                            })
                            break
        except Exception as e:
            pass

print(f'Total matching lines across repo: {len(matches)}')
from collections import Counter
file_counts = Counter(m['file'] for m in matches)
for f, c in file_counts.most_common(30):
    print(f'{c:4d} matches in {f}')
